'use strict';
(async()=>{
 const fs=require('node:fs');
 const body={sourcecode:"(input) => {\n  const file = DriveApp.getFileById(input.fileId);\n  const info = {sourceFileId:file.getId(), sourceName:file.getName(), sourceBytes:file.getSize(), mimeType:file.getMimeType(), inspectedAt:new Date().toISOString()};\n  if (info.sourceBytes > input.maxUnzipBytes) {\n    const report = {status:\"BLOCKED_LARGE_ARCHIVE\", reason:\"Archive exceeds configured Apps Script in-memory unzip safety threshold.\", metadata:info, archiveModified:false};\n    const output = DriveApp.createFile(\"takeout-archive-inspection-\"+input.runId+\".json\", JSON.stringify(report,null,2), MimeType.PLAIN_TEXT);\n    return {status:report.status, driveFileId:output.getId(), driveFileUrl:output.getUrl(), sourceBytes:info.sourceBytes, archiveModified:false};\n  }\n  const entries = Utilities.unzip(file.getBlob()).map(b=>({name:b.getName(), bytes:b.getSize()}));\n  const report={status:\"ENUMERATED\", metadata:info, entries:entries, archiveModified:false};\n  const output = DriveApp.createFile(\"takeout-archive-inspection-\"+input.runId+\".json\", JSON.stringify(report,null,2), MimeType.PLAIN_TEXT);\n  return {status:\"ENUMERATED\", driveFileId:output.getId(), driveFileUrl:output.getUrl(), entryCount:entries.length, archiveModified:false};\n}",arguments:{fileId:"1MxvFWzM9b-HnZlfr29kzmbqx5BbBetOK",runId:"drive_takeout_inventory_20261007_1",maxUnzipBytes:25000000}};
 const url="https://script.google.com/macros/s/AKfycbxz7tkba4wl-wWzDn90iuh0us2l2EUD3AYV9HyVJckETKGjhPKFthnqPyYmcOPOk_g5FA/exec";
 const response=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),redirect:'follow'});
 const text=await response.text();
 if(!response.ok)throw new Error('Apps Script HTTP '+response.status+': '+text.slice(0,500));
 let result;try{result=JSON.parse(text)}catch(e){throw new Error('Endpoint did not return JSON: '+text.slice(0,500))}
 if(!result.driveFileId||!result.driveFileUrl)throw new Error('Missing Drive output evidence: '+JSON.stringify(result));
 fs.writeFileSync("untrusted AI/meta-procedure/Procedures/DriveTakeoutInventory/latest-result.json",JSON.stringify(result,null,2));
 console.log(JSON.stringify(result));
})().catch(e=>{console.error(e);process.exitCode=1});
